import java.util.Scanner;

class Cat {
    String name;
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String who1 = sc.next();
        String who2 = sc.next();

        Cat c1 = new Cat();
        c1.name = who1;
        Cat c2 = new Cat();
        c2.name = who2;
        Cat c3 = new Cat();

        System.out.println(c1.name);
        System.out.println(c2.name);
        System.out.println(c3.name);
    }
}
